window.NMR_EXPERIMENT = Object.freeze({"meta":{"number":"1","slug":"chapter-1","kind":"chapter","title":"Basics and Spectrometer Performance Checks","titleZh":"基础与谱仪性能检查","pages":[{"id":"source-11","pdfPage":11,"bookPage":1,"en":"content/pages/source-11.en.html","zh":"content/pages/source-11.zh.html"},{"id":"source-12","pdfPage":12,"bookPage":2,"en":"content/pages/source-12.en.html","zh":"content/pages/source-12.zh.html"},{"id":"source-13","pdfPage":13,"bookPage":3,"en":"content/pages/source-13.en.html","zh":"content/pages/source-13.zh.html"},{"id":"source-14","pdfPage":14,"bookPage":4,"en":"content/pages/source-14.en.html","zh":"content/pages/source-14.zh.html"},{"id":"source-15","pdfPage":15,"bookPage":5,"en":"content/pages/source-15.en.html","zh":"content/pages/source-15.zh.html"},{"id":"source-16","pdfPage":16,"bookPage":6,"en":"content/pages/source-16.en.html","zh":"content/pages/source-16.zh.html"},{"id":"source-17","pdfPage":17,"bookPage":7,"en":"content/pages/source-17.en.html","zh":"content/pages/source-17.zh.html"},{"id":"source-18","pdfPage":18,"bookPage":8,"en":"content/pages/source-18.en.html","zh":"content/pages/source-18.zh.html"},{"id":"source-19","pdfPage":19,"bookPage":9,"en":"content/pages/source-19.en.html","zh":"content/pages/source-19.zh.html"},{"id":"source-20","pdfPage":20,"bookPage":10,"en":"content/pages/source-20.en.html","zh":"content/pages/source-20.zh.html"},{"id":"source-21","pdfPage":21,"bookPage":11,"en":"content/pages/source-21.en.html","zh":"content/pages/source-21.zh.html"},{"id":"source-22","pdfPage":22,"bookPage":12,"en":"content/pages/source-22.en.html","zh":"content/pages/source-22.zh.html"},{"id":"source-23","pdfPage":23,"bookPage":13,"en":"content/pages/source-23.en.html","zh":"content/pages/source-23.zh.html"},{"id":"source-24","pdfPage":24,"bookPage":14,"en":"content/pages/source-24.en.html","zh":"content/pages/source-24.zh.html"},{"id":"source-25","pdfPage":25,"bookPage":15,"en":"content/pages/source-25.en.html","zh":"content/pages/source-25.zh.html"},{"id":"source-26","pdfPage":26,"bookPage":16,"en":"content/pages/source-26.en.html","zh":"content/pages/source-26.zh.html"},{"id":"source-27","pdfPage":27,"bookPage":17,"en":"content/pages/source-27.en.html","zh":"content/pages/source-27.zh.html"},{"id":"source-28","pdfPage":28,"bookPage":18,"en":"content/pages/source-28.en.html","zh":"content/pages/source-28.zh.html"},{"id":"source-29","pdfPage":29,"bookPage":19,"en":"content/pages/source-29.en.html","zh":"content/pages/source-29.zh.html"},{"id":"source-30","pdfPage":30,"bookPage":20,"en":"content/pages/source-30.en.html","zh":"content/pages/source-30.zh.html"},{"id":"source-31","pdfPage":31,"bookPage":21,"en":"content/pages/source-31.en.html","zh":"content/pages/source-31.zh.html"},{"id":"source-32","pdfPage":32,"bookPage":22,"en":"content/pages/source-32.en.html","zh":"content/pages/source-32.zh.html"},{"id":"source-33","pdfPage":33,"bookPage":23,"en":"content/pages/source-33.en.html","zh":"content/pages/source-33.zh.html"}],"figurePlacements":{"source-11":[{"source":0,"before":"第1部分 家庭化"}],"source-12":[{"source":0,"before":"图 1.1 图表:以单位采集时间的水平轴绘制了常用的数据处理窗口函数:指数式 (固体线);高斯指数式 (点线); 45°转移的弦 (线)."}],"source-15":[{"source":0,"before":"图 1.2"}],"source-16":[{"source":0,"before":"图1.3 根据布鲁克Avance DRX 500 MHz谱仪采用BBO探测器,无样本旋转的CDCl3样本的残余溶剂信号对观察到的线形的影响.各种光谱条件是:优化"}],"source-18":[{"source":0,"before":"图1.4 360°脉冲校准,基于在变长度在共振脉冲激励后的信号观察. 360°脉冲是第二个零点:其中一半导致第一个零点,而1"},{"source":1,"before":"图1.5 1H信号与噪音比分为2150:1用于0.1% ETB样本 (20 Hz旋转) 使用采用采用297 K的布鲁克AV-III 800 MHz谱仪,配备了T"}],"source-26":[{"source":0,"before":"图 A1.2-1 探测器调整显示器 (wobb命令) 任意探测器头.点垂直线是调整的核的共振频率.固体红线:已实现正确调整;固体黑线:调整和匹配都不正确."}],"source-29":[{"source":0,"before":"图A1.3-1 500 MHz 1H光谱中水在CDCl3中 298 K."},{"source":1,"before":"图A1.3-2 125 MHz 13C频谱中基因化在CDCl3中,在298K."}],"source-30":[{"source":0,"before":"图A1.4 (a) 使用采用BBO探测器和无样本旋转的布鲁克 Avance 500 MHz谱仪获得的CDCl3样本的残余溶剂信号对观察的线形的影响.各种状条件是"}],"source-31":[{"source":0,"before":"图A1.4 (继续)"}],"source-32":[{"source":0,"before":"图A1.5-1 显示完成的光运行,使用0.1%ETB样本的1H频谱在800MHz时获得.这显示了p1在5μs到40μs的步骤中变化.注意标志器线表示显示的第一频"}]},"chapter":"Basics and Spectrometer Performance Checks","navigationSections":[{"id":"section-source-11-1","pageId":"source-11","title":"OVERVIEW","titleZh":"概述","kind":"section"},{"id":"section-source-11-2","pageId":"source-11","title":"SAMPLE AND SPECTROMETER REQUIREMENTS","titleZh":"样品与谱仪要求","kind":"section"},{"id":"section-source-11-3","pageId":"source-11","title":"ACTIVITIES","titleZh":"实验内容","kind":"section"},{"id":"section-source-11-4","pageId":"source-11","title":"Part 1—Familiarization","titleZh":"第 1 部分——熟悉操作","kind":"part"},{"id":"section-source-13-5","pageId":"source-13","title":"Part 2—Shimming and Lineshape","titleZh":"第 2 部分——匀场与线形","kind":"part"},{"id":"section-source-17-6","pageId":"source-17","title":"Part 3—Pulse Calibration and Sensitivity for 1H","titleZh":"第 3 部分——1H 脉冲校准与灵敏度","kind":"part"},{"id":"section-source-19-7","pageId":"source-19","title":"Part 4—Pulse Calibration and Sensitivity for 13C","titleZh":"第 4 部分——13C 脉冲校准与灵敏度","kind":"part"},{"id":"section-source-20-8","pageId":"source-20","title":"Part 5—Viewing and Editing Text Files in TopSpin","titleZh":"第 5 部分——在 TopSpin 中查看和编辑文本文件","kind":"part"},{"id":"section-source-22-9","pageId":"source-22","title":"SUMMARY","titleZh":"总结","kind":"section"},{"id":"section-source-22-10","pageId":"source-22","title":"APPENDIX 1.1 STANDARD PARAMETER SETS","titleZh":"附录 1.1 标准参数集","kind":"section"},{"id":"section-source-25-11","pageId":"source-25","title":"APPENDIX 1.2 PROBE TUNING","titleZh":"附录 1.2 探头调谐","kind":"section"},{"id":"section-source-28-12","pageId":"source-28","title":"APPENDIX 1.3 QUININE SPECTRA","titleZh":"附录 1.3 奎宁谱","kind":"section"},{"id":"section-source-28-13","pageId":"source-28","title":"APPENDIX 1.4 LINESHAPE EFFECTS OF NONSPINNING SHIMS","titleZh":"附录 1.4 非旋转匀场线圈对线形的影响","kind":"section"},{"id":"section-source-28-14","pageId":"source-28","title":"APPENDIX 1.5 PULSE WIDTH CALIBRATION WITH PAROPT","titleZh":"附录 1.5 使用 PAROPT 校准脉冲宽度","kind":"section"}]},"english":{"source-11":"<h3>CHAPTER 1</h3>\r\n<h3>Basics and Spectrometer Performance Checks</h3>\r\n<h3>OVERVIEW</h3>\r\n<p>This chapter’s exercises are designed to introduce some of the fundamentals of NMR data acquisition and processing. We will look into some of the details of shimming, pulse calibration, sensitivity checking, and data acquisition and processing. The material covered in this chapter is in Chapters 2 and 3 of the Claridge book.</p>\r\n<p>Note: For each laboratory, we recommend that you make a new experiment name such as “chapter-1” and use a new experiment number (expno) for each experiment you run. Don’t lose data by accidentally overwriting it! If in doubt always run an experiment in a new expno.</p>\r\n<h3>SAMPLE AND SPECTROMETER REQUIREMENTS</h3>\r\n<p>This chapter’s exercises will use samples A, B, C, and D. Since the NMR experiments in this chapter are simple 1D acquisitions, there are no special requirements for the spectrometer hardware.</p>\r\n<h3>ACTIVITIES</h3>\r\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-011-fig-1.webp\" alt=\"Figure from source page 11.\" loading=\"lazy\"></figure>\r\n<h3>Part 1—Familiarization</h3>\r\n<p>1. Set up (using different experiment numbers) 1H and 13C datasets using your spectrometer’s standard parameter sets and procedures (discussion and examples of the standard parameter sets used at in the authors’ facility are presented in Appendix 1.1).</p>\r\n\r\n","source-12":"<p>2. Load the quinine/CDCl3 sample into the magnet and complete the locking and shimming process. Tune the probe for both 1H and 13C (command wobb or cwobb or atmm/atma—for a discussion of probe tuning, see Appendix 1.2). If you are not experienced with probe tuning please obtain assistance from the spectrometer administrator for this step. Note that we will expect that probe tuning be done whenever a sample is changed or a new nucleus observed, even if it is not explicitly mentioned in the text. 3. Acquire the data and process the spectra using manual phasing, and check the chemical shift referencing. Edit the title text (Title tab or setti) to reflect the experiment and sample used. 4. Plot both spectra, including peak-picking and integrations for the 1H. Check that the integration values look reasonable. 5. Note the effect of exponential multiplication by processing your data using ef versus ft. Try different values of lb to assess the impact of differing exponential multiplication functions upon the spectrum. 6. Using Figure 1.1 as a guide, try processing the 1H data using a couple of different window functions, such as Gaussian and sine-bell. To select one of these use the wm command. In the popup window use the pulldown to select the desired window function, then enter the necessary controlling parameters in the appropriate fields: use gb and lb for Gaussian and ssb for sine-bell. Starting values for these parameters would be as follows:</p>\r\n<p>gb 0.3 (range is 0–1)</p>\r\n<p>lb 20.5 (approximate value is ca. 2 (1/AQ))</p>\r\n<p>ssb 1 or 2 (1 for sine-bell, 2 for cosine)</p>\r\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-012-fig-1.webp\" alt=\"Figure from source page 12.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure 1.1 Three frequently used data processing window functions plotted with the horizontal axis representing the unit acquisition time: exponential (solid line); Gaussian-exponential (dotted line); and a 45° shifted sine-bell (dashed line).</p>\r\n","source-13":"<p>To apply the window function to the raw NMR data (the Free Induction Decay or FID), click the OK button in the popup window. Then to generate the new spectrum use either the ft or fp command (fp applies the previously-determined phase correction, using processing parameters PHC0 and PHC1, to the spectrum, whereas ft generates a spectrum without phase correction). Feel free to experiment with other window functions—the original FID remains unchanged, only the spectrum changes. 7. Print out at least three spectra obtained with different processing functions. Show the areas of the spectra where the processing function has the most impact. 8. Examples of the 1H and 13C spectra of quinine at 500/125 MHz are shown in Appendix 1.3.</p>\r\n<h3>Part 2—Shimming and Lineshape</h3>\r\n<p>1. Replace the quinine sample with the CHCl3/acetone-d6 sample. Before locking, note the signal in the lock display: why is there no lock signal wiggle apparent? 2. Create a new dataset (edc or new command). Lock on acetone-d6. Make sure the sample spinning is on. 3. Shim Z1, Z2, and Z3 by hand (using either the BSMS physical keypad or the command bsmsdisp to display the software shimming interface) to get the best lock level. Keep the lock power low to avoid saturating the lock signal (a saturated lock signal may drift up and down even when shims are not being changed, and may be less responsive than normal to shim changes). 4. Run a 1H spectrum in the new dataset using standard parameters. Contrary to normal practice, for this spectrum set the chemical shift of the CHCl3 peak to 0 and change the displayed axis units from ppm to Hz (h/p icon in the upper icon bar). 5. Copy the data to a new expno, using either wrpa and re commands (e.g., wrpa 3 followed by re 3 to duplicate the current dataset to experiment number 3 and then to load it) or the new command. Optimize the O1, SW, and TD parameters to give a data (FID) acquisition time (AQ) of ca. 10 s—this ensures adequate digital resolution in the resulting spectrum. Set, or check that, the SI parameter equal to TD/2. Rerun the spectrum and take a close look at the CHCl3 peak. Expand the spectrum ca. 6 30 Hz around the CHCl3 peak and define your expanded region as the plot region. Using the cursor left-click and drag mode, measure the linewidth</p>\r\n","source-14":"<p>and lineshape by hand, at ½-height (for linewidth) and at 0.55% and 0.11% of the total height (for lineshape, or “hump”) of the line. Make a note of your results. Then type humpcal to use the au program to make the same measurements using a peak-fitting routine. Does it meet specification? Note that the lineshape specifications are specific to the instrument and probe you are using, so you will need to check the instrument documentation or with the spectrometer administrator to find this information. If neither is readily available, reasonable values for a conventional probe would be a ½-height linewidth of less than 0.8 Hz, and a lineshape of less than 7.0 and 14.0 Hz for the 0.55% and 0.11% measurements, respectively. For making the linewidth measurements by hand it can be advantageous to set the cy equal to 100 or 1000, whereby, for example, the linewidth at 0.55% height would be measured when the cursor height reading is 0.55 or 5.5 cm, respectively. Be aware that if the zoom region being displayed is too narrow, the cursor may not display the correct height value for its location. Usually this can be remedied by broadening the displayed zoom region (i.e., alter the zoom display to include more Hz). An example of the lineshape measurement is shown in Figure 1.2. 6. Work on the shimming to improve the lineshape. If the lineshape is asymmetric, Z2 and Z4 need work. Check also Z3 and Z5. If Z4 is altered re-shim Z1, 2, and 3—often a good strategy is to alter Z4 by 500 units, re-shim, and then observe the spectrum to see if the lineshape has improved. If it has, repeat the process by changing Z4 another 500 units in the same direction until the optimum lineshape is obtained. If the lineshape is worse, change</p>\n<p>back 500 units in the other direction from the first change, re-shim and reacquire. If Z5 is altered re-shim Z1 and Z3, then Z2. Some of the Z-axis (spinning) shim functions’ effects upon the lineshape are shown in Figure 1.3. 7. Reacquire spectra as needed. 8. Turn off sample spinning and optimize the low-order nonspinning shims as follows: a. Z1, X, XZ, XZ2 b. Z1, Y, YZ, YZ2</p>\r\n<p>c. XY, X2 2 Y2, XZY d. X, Y. Note that on some spectrometers (equipped with “matrix” shims) the physical keypad operation for nonspinning shims requires selection of</p>\n","source-15":"<p>the X, Y, XY, or X<sup>2</sup> − Y<sup>2</sup> button followed by the required Z function. For example, to adjust the X shim press the X button followed by the Z0 button; to adjust the YZ2 shim press the Y button followed by the Z2 button, etc. Some of the effects of the nonspinning shims upon the lineshape are shown in Appendix 1.4.</p>\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-015-fig-1.webp\" alt=\"Figure from source page 15.\" loading=\"lazy\"></figure>\n<p class=\"figure-caption\">Figure 1.2 <sup>1</sup>H lineshape test of a 0.1% CHCl<sub>3</sub>/acetone-d<sub>6</sub> sample recorded on a Bruker AV-III 800 MHz spectrometer equipped with a TXI probe at 298 K. The nonspinning linewidth at ½-height, 0.55% and 0.11% height is measured using humpcal as 0.58, 5.6, and 11.8 Hz. The manual measurement of the linewidth and ca. 0.55% height is shown as well. Note the “Value = 0.56 rel” text displayed in the cursor information area on the left side of the spectrum window. This “Value” is the height of the datapoint at the cursor’s location relative to the peak height (cy), which was set to 100 cm. When measuring lineshape by hand you may not be able to get a height of exactly 0.55%; just use a very close height or interpolate between adjacent data points. Low-frequency (~10 Hz) noise from floor vibration is seen at the base of the peak.</p>\n<p>9. Restart spinning and touch up Z1, Z2, and Z3. Reacquire. Decide if your result is good enough; if it is not, repeat the shimming process again. 10. Acquire your last, best spectrum with spinning on. Process and plot. Include your lineshape results and spinning status in the title of the printout. Did you achieve a lineshape that met specifications?</p>\n","source-16":"<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-016-fig-1.webp\" alt=\"Figure from source page 16.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure 1.3 Impact of various shims upon the observed lineshape of the residual solvent signal from a CDCl3 sample obtained on a Bruker Avance DRX 500 MHz spectrometer equipped with a BBO probe and no sample spinning. The various shim conditions are: optimized (A); Z shim is reduced (B) or increased (C) by 20; Z2 shim is reduced (D) or increased (E) by 100; Z3 shim is reduced (F) or increased (G) by 500; Z4 shim is reduced (H) or increased (I) by 4000.</p>\r\n<p>11. Turn spinning off and reacquire the spectrum in a new expno. Print this with the lineshape information and spinning status again in the title. 12. Save your shim settings using the wsh command (e.g., wsh chapter1-acet.shm).</p>\r\n","source-17":"<h3>Part 3—Pulse Calibration and Sensitivity for 1H</h3>\r\n<p>1. In order for the spectrometer to obtain its highest sensitivity several things have to be optimized. Put the 0.1% ethylbenzene sample in the magnet, spin, lock on CDCl3, and shim. Use a new expno. Tune the probe for <sup>1</sup>H. Run the <sup>1</sup>H spectrum using standard parameters. 2. Now set the pulse program (PULPROG) to zg, NS = 1, DS = 0, and P1 = 3 µs. Check that the transmitter power level (parameter PL1) is the correct value for your spectrometer. If this information is not readily available a power level of 0 dB will usually be acceptable. Check the receiver gain using rga. Rerun and phase. Note: In the Bruker convention, a more positive power (dB) level signifies less RF power, e.g., 0 dB is a typical moderately-high power while 120 dB is very low (close to zero) power. Thus the PL value refers to an attenuation (power-reduction) level from a reference power level. 3. Copy data and use a new expno. We will now determine the 90-degree pulse (p90) length using the 360-degree method. A 360°</p>\n<p>pulse will give almost zero signal, with less than 360° giving a weak negative peak and more than 360° giving a weak positive one. Enter a value for P1 that is about four times the specified p90 value for the probe you are using (a typical 1H high power pulse length is expected to be in the order of 10 µs). Rerun and apply the existing phase correction (efp). Adjust the P1 value and reacquire the data until you get a spectrum with almost zero signal intensity. The p90 value will be equal to this P1 divided by 4. There is also an automated routine available for carrying out this process called paropt, the use of this is presented in Appendix 1.5 (Figure 1.4). 4. Copy and use a new expno. For P1 enter the value you determined above for the p90, and run one scan after checking the receiver gain setting with rga. Carefully phase the resulting spectrum. 5. New expno. Adjust the acquisition and processing parameters as follows: D15 60 s, O1P5 4 ppm, SW5 10 ppm, TD5 32K (i.e. 32768 points), LB5 1.0, and SI5 16K. Be sure to have the calibrated parameters for p90 (P1) entered. Rerun one scan, process using ef, and determine the signal-to-noise ratio. This is most easily done through the use of the sinocal program. Type sinocal to start the routine, which will then ask for several inputs. The signal region is chosen to be the methylene quartet, defined between 2.8 and 2.5 ppm; the noise region is defined between 7.1 and 2.8 ppm; the noise width is entered as the ppm equivalent of 200 Hz (i.e., 0.4 ppm at 500 MHz). Print this spectrum with the s/n value included in the title text (Figure 1.5).</p>\r\n","source-18":"<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-018-fig-1.webp\" alt=\"Figure from source page 18.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure 1.4 A 360° pulse calibration that is based on observation of the signal after variable length on-resonance pulse excitations. The 360° pulse is the second null point: half of that leads to first null while ¼ or ¾ of 360° leads to the maximum positive or negative signal.</p>\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-018-fig-2.webp\" alt=\"Figure from source page 18.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure 1.5 1H signal-to-noise ratio measured as 2150:1 for a 0.1% ETB sample (20 Hz spinning) using a Bruker AV-III 800 MHz spectrometer equipped with a TXI probe at 297 K. This ratio is calculated as the methylene peak height compared to the twice the RMS noise level of a 200-Hz-wide band of random noise in the spectrum.</p>\r\n","source-19":"<p>6. OPTIONAL. Obtain your spectrometer administrator’s permission before carrying out steps 7–9. 7. Create a new dataset in a new expno. Using the probe tuning routine, detune the probe so that the tuning dip is moved away from the correct 1H frequency by ca. 1 MHz. 8. Repeat the p90 calibration procedure. 9. New expno. Repeat the sensitivity-test scan using the new p90 calibration value, run sinocal on the resulting spectrum and print the spectrum out. Is this result different from that obtained in part 5? Why or why not?</p>\r\n<h3>Part 4—Pulse Calibration and Sensitivity for 13C</h3>\r\n<p>1. Put in the 10% ETB sample, spin, lock on CDCl3, and shim. Set up a new expno. 2. Run the 1H spectrum to check that the shimming is acceptable. 3. Set up a 13C acquisition using the standard parameters. We assume here that the PL1 value in the standard parameters is correct. 4. Check the probe tuning for both 1H and 13C. 5. Acquire a 13C spectrum with 8 scans. Check that it looks OK. 6. Copy the data to a new expno and set</p>\r\n<h3>DS = 0,</h3>\r\n<h3>NS = 1,</h3>\r\n<p>PULPROG = zgpg and P1 = 5 µs. Run this and phase the spectrum carefully. 7. Determine the <sup>13</sup>C p90 in the same fashion as in Part 3. Use a long enough D1 delay (30–60 s) between acquisitions so that the signal does not get saturated. 8. Copy data to a new expno and set up the parameters for the <sup>13</sup>C sensitivity check with <sup>1</sup>H decoupling as follows:</p>\r\n<h3>PULPROG</h3>\r\n<p>zgdc</p>\r\n<h3>RG</h3>\r\n<p>maximum value (or close to it) for your spectrometer</p>\r\n<h3>D1</h3>\r\n<p>300 s</p>\r\n<h3>O1P</h3>\r\n<p>80 ppm</p>\r\n<h3>SW</h3>\r\n<p>200 ppm</p>\r\n<h3>P1</h3>\r\n<p>Correct p90 value</p>\r\n<h3>TD</h3>\r\n<p>256K</p>\r\n<h3>O2P</h3>\r\n<p>ca. 5 ppm (i.e., the approximate center of the ETB 1H spectrum)</p>\r\n<h3>CPDPRG2</h3>\r\n<p>waltz16</p>\r\n<h3>PCPD2</h3>\r\n<p>Use the value from your spectrometer’s standard 13C parameters</p>\r\n<h3>PL12</h3>\r\n<p>Use the value from your spectrometer’s standard 13C parameters</p>\r\n<h3>LB</h3>\r\n<p>0.3</p>\r\n<h3>SI</h3>\r\n<p>128K</p>\r\n","source-20":"<p>Note: The PCPD2/PL12 parameter combination is the calibration for a 1H p90 of ca. 80 µs (500 MHz spectrometer) to 60 µs (800 MHz). This pulse is used as part of the waltz16 composite-pulse-decoupling sequence (CPDPRG2) to give uniform 1H decoupling across the 1H spectrum width. Rerun one scan, process, and determine the signal-to-noise ratio. Use the sinocal routine with the following inputs: signal region between 130 and 125 ppm; noise region defined between 125 and 29 ppm; noise width of 40 ppm. Print this spectrum with the s/n value included in the title text.</p>\r\n<h3>Part 5—Viewing and Editing Text Files in TopSpin</h3>\r\n<p>1. Macros, au programs, and pulse programs are examples of types of text files that you will work with as a normal part of spectrometer operation. The sinocal program we used for the signal-to-noise ratio calculation is an example of an au program. Often it is useful to be able to view or even edit your own copies of these types of files. In the following steps we will take a look at each one of these types of files. 2. Macros are files which contain a series of TopSpin commands to be executed sequentially. Type edmac to open a menu of macros which are included with the software. We can edit our own macro as an example, in this case to acquire data and process it automatically. Type edmac zgefp.xyz (where xyz 5 your initials) followed by the return key to enter the editing mode for the new macro titled “zgefp.xyz.” In the editing window enter the following as shown:</p>\r\n<p>rga zg ef apk Terminating the editing process is slightly different in different versions of TopSpin. For TopSpin 1.3, click the OK button at the bottom left of the edmac window (or type alt-o) to save your macro and exit the editor. For TopSpin versions 2, go to the File pulldown and select Close, then confirm the save request in the popup window to exit the editor. Whenever you want to execute this macro simply type zgefp.xyz and the series of commands entered in the macro will be carried out. 3. Au programs are programs that can operate on the spectrometer or on data. Here we will create a version of an au program that we</p>\r\n","source-21":"<p>use at our facility called “standard.” This is used to set the spectrometer up to be left with the standard CDCl3 sample in the magnet after someone has finished using the spectrometer. It assumes that a 1H dataset is loaded as the current dataset. Type edau standard.xyz (again, xyz 5 your initials) to open the au program editor with the new file named standard.xyz. In the editor window enter the following text:</p>\r\n<p>/*file location: /opt/topspin/exp/stan/nmr/au/src/standard.xyz */</p>\r\n<p>/*this program will read shim file shims.probe and lock on CDCl3</p>\r\n<p>solvent */</p>\r\n<p>/*this program should be executed from a 1H dataset which DOES NOT</p>\r\n<p>contain critical data*/</p>\r\n<p>char solvent[20]; /*initialize the character variable named ‘solvent’ */</p>\r\n<p>/*load the current dataset */ FETCHPAR(“SOLVENT”, solvent) /*save the current solvent value into ‘solvent’ */ STOREPAR(“SOLVENT”, “CDCl3”) /*set the solvent variable to CDCl3 */ RSH(“shims.probe”) /*load the shims from file ‘shims.probe’ */</p>\r\n<h3>GETCURDATA</h3>\r\n<p>/*initialize interfaces */</p>\r\n<h3>II</h3>\r\n<p>/*set up lock for new solvent */</p>\r\n<h3>LOPO</h3>\r\n<p>/*lock on CDCl3 */ STOREPAR(“SOLVENT”, solvent) /*set solvent parameter back to original value */</p>\r\n<h3>LOCK</h3>\r\n<p>/*finish the au program */</p>\r\n<h3>QUIT</h3>\r\n<p>Note that the text between the /* and */ symbols is included as commentary to help explain the operation of this au program, so it does not have to be included when editing your au program. If you do include it in your program it will be treated as commentary and will not be compiled as part of the program. If you do include comments be sure to include the designating symbols (/* */) correctly. Terminating the editing process is slightly different in different versions of TopSpin. For TopSpin 1.3, after entering all the lines, click the SAVE, EXIT, and COMPILE button at the bottom of the editor window (or type alt-x) to save and compile the program and exit the editor window. For TopSpin versions 2, first click the COMPILE button to compile the program, then go to the File pulldown and select Close, then confirm the save request in the popup window to exit the editor. Assuming the compilation completes successfully, to execute this program simply type standard.xyz. 4. Type edpul to open a menu of all the pulse programs on the spectrometer. Choose, for example, “zg” click the EDIT button at the bottom of the window to open it. You will now see the syntax of a simple pulse program. In addition, the PulseProg tab in the spectrum window will show you the pulse program in the</p>\r\n","source-22":"<p>current experiment. We will edit a pulse program as part of Chapter 3 activities.</p>\r\n<h3>SUMMARY</h3>\r\n<p>The lab report should include the following:</p>\r\n<p>1. Quinine: Three 1H spectra, each processed with a different window function, and the 13C spectrum. 2. 0.3% CHCl3 in acetone-d6: Lineshape spectra with and without sample spinning, with results in the title text. 3. 0.1% ETB sample: 1H spectrum, spectrum showing ca. 360° pulse, sensitivity spectrum with results in the title text. 4. 10% ETB sample: Standard 13C spectrum, sensitivity spectrum with results in the title text. 5. Suggested questions for consideration: a. What is the significance of the 90° pulse? b. When you put the lineshape sample into the magnet, why was</p>\r\n<p>there not a lock wiggle signal in the lock window as there was when changing to another CDCl3 sample? c. Why does the residual solvent peak in your first lineshape-</p>\r\n<p>sample spectrum look like it does? Why does it show its specific multiline pattern? d. Can you make any preliminary assignments for the 1H and 13C</p>\r\n<p>spectra of quinine? e. If you measured the 1H sensitivity after detuning the probe (OPTIONAL), what accounts for the difference between the two results, and why? Do you notice any lineshape change correlating with a sensitivity change?</p>\r\n<h3>APPENDIX 1.1 STANDARD PARAMETER SETS</h3>\r\n<p>In the context of this work, when we use the term “standard parameters” we are referring to the parameters used to obtain a routine 1D 1H or 13C spectrum on a typical organic sample. Thus, this is referring to the most basic type of NMR experiment setup. The parameters in these experiments relevant to the NMR data acquisition are the RF pulse width and pulse power, the precise spectrometer frequency, or transmitter offset, the sweep width, the number of data points acquired, and the interpulse (or relaxation) delay. In the case of 13C acquisition, there are parameters for 1H decoupling including the</p>\r\n","source-23":"<p>RF power, the decoupling pulse width, the decoupling pulse program, and the transmitter offset for the decoupling channel. The parameter sets also include the required data processing parameters, such as the type of window function applied to the FID and the settings for that function, the number of real data points in the final spectrum, and the chemical shift referencing information.</p>\r\n<p>The Bruker TopSpin software includes a large number of parameter sets that usually will be installed as part of the software installation when the spectrometer is first set up. The parameter sets for routine</p>\r\n<p>1H or 13C observation are named PROTON and C13CPD, respectively. However, these parameter sets will not work as is because by default they do not include the relevant pulse calibration information for a given spectrometer and probe combination. An additional command, getprosol, must be used to load the correct pulse calibration information from the “prosol” (probe and solvent information) table.</p>\r\n<h3>1D</h3>\r\n<p>This proceeds as follows:</p>\r\n<p>rpar PROTON all load parameter set PROTON including all subsets getprosol update acquisition parameters with correct calibrations</p>\r\n<p>Note that in order for this to work correctly the “probe” variable must be set correctly, using the command edhead, and the prosol table must be set up correctly. We show an example of the prosol table in Appendix 4.1.</p>\r\n<p>At the authors’ facility we choose to operate in a different fashion. We set up and save our own customized parameter sets on each spectrometer for each probe in common use. Our parameter sets contain all the relevant calibration information, so the user simply has to load the correct parameter set prior to acquiring data, as follows:</p>\r\n<p>rpar h1.cryo all load local parameter set for 1H observation using cryoprobe</p>\r\n<p>The specifics of the standard parameter sets will vary somewhat for individual spectrometers and probes. Below are examples from our facility for a Bruker Avance DRX-500 spectrometer equipped with a 5-mm TXI cryoprobe.</p>\r\n","source-24":"<p>1H standard parameters (parameter set h1.cryo)</p>\r\n<h3>PULPROG:</h3>\r\n<p>zg30</p>\r\n<h3>32K (K 5 1024)</h3>\r\n<h3>TD:</h3>\r\n<h3>NS:</h3>\r\n<p>8</p>\r\n<h3>DS:</h3>\r\n<p>2</p>\r\n<h3>SWH:</h3>\r\n<p>6510.40 (Hz, ca. 13 ppm)</p>\r\n<h3>AQ:</h3>\r\n<p>2.52 s</p>\r\n<h3>RG</h3>\r\n<p>set using rga or manually optimized for each sample</p>\r\n<h3>D1:</h3>\r\n<p>1.00 s</p>\r\n<h3>NUC1:</h3>\r\n<h3>1H</h3>\r\n<p>8.0 µs</p>\r\n<h3>P1:</h3>\r\n<p>(1)1.6 dB</p>\r\n<h3>PL1:</h3>\r\n<h3>SFO1:</h3>\r\n<p>499.89250 MHz</p>\r\n<h3>O1 (O1P):</h3>\r\n<p>2500 Hz (ca. 5.0 ppm)</p>\r\n<h3>SI:</h3>\r\n<p>16k</p>\r\n<h3>LB:</h3>\r\n<p>0.3 (Hz)</p>\r\n<p>13C standard parameters (parameter set c13.cryo)</p>\r\n<h3>PULPROG:</h3>\r\n<p>zgpg30</p>\r\n<h3>TD:</h3>\r\n<p>32k</p>\r\n<h3>NS:</h3>\r\n<p>256</p>\r\n<h3>DS:</h3>\r\n<p>8</p>\r\n<h3>SWH:</h3>\r\n<p>30303.03 (Hz, ca. 240 ppm)</p>\r\n<h3>AQ:</h3>\r\n<p>0.54 s</p>\r\n<h3>RG</h3>\r\n<p>usually the maximum value (or close to it) for your spectrometer</p>\r\n<h3>D1:</h3>\r\n<p>2.00 s</p>\r\n<h3>NUC1:</h3>\r\n<h3>13C</h3>\r\n<p>16.0 µs</p>\r\n<h3>P1:</h3>\r\n<p>23 dB</p>\r\n<h3>PL1:</h3>\r\n<h3>SFO1:</h3>\r\n<p>125.71124 MHz</p>\r\n<h3>O1 (O1P):</h3>\r\n<p>13,800 Hz (ca. 110 ppm)</p>\r\n<h3>CPDPRG2:</h3>\r\n<p>waltz16</p>\r\n<h3>NUC2:</h3>\r\n<h3>1H</h3>\r\n<p>80.0 µs</p>\r\n<h3>PCPD2:</h3>\r\n<h3>PL2</h3>\r\n<p>120 dB</p>\r\n<h3>PL12:</h3>\r\n<p>21.0 dB</p>\r\n<h3>PL13:</h3>\r\n<p>24.0 dB</p>\r\n<h3>SFO2:</h3>\r\n<p>499.89200 MHz</p>\r\n<h3>O2 (O2P):</h3>\r\n<p>2000 Hz (ca. 4.0 ppm)</p>\r\n<h3>SI:</h3>\r\n<p>16k</p>\r\n<h3>LB:</h3>\r\n<p>3.0 (Hz)</p>\r\n","source-25":"<h3>APPENDIX 1.2 PROBE TUNING</h3>\r\n<p>If you have not carried out the probe tuning operation before, obtain the assistance of your spectrometer administrator or other qualified individual before attempting the following procedures.</p>\r\n<p>Note: If your probe is equipped with motor-controlled tuning and matching please skip to the Probe Tuning—Using ATMM or ATMA routine section at the end of this Appendix.</p>\r\n<h3>Tuning the 1H Coil—All Probes</h3>\r\n<p>1. We will tune the 1H coil first. Turn off the sample spinning. Set up a 1H dataset. 2. Type acqu to go to the acquisition window, then type wobb or cwobb (the latter for some systems with cryoprobes) to start the probe tuning (“wobble”) routine. 3. The computer screen will show a trace with a dip in it; hopefully the dip will be close to the correct frequency in the center of the screen. If there is no dip, click the WOBB-SW button to the left of the screen, and enter a new value in the correct field of the screen that pops up. The default SW is 4 MHz; try 12 or 16 MHz if it needs changing. 4. When you have confirmed that there is a dip present, go to the magnet and adjust the yellow-labeled tune and match screws (screws may have large or small heads—do not confuse them with the probe mounting screws which are usually brass-colored) under the probe to bring the minimum of the dip to the center of the screen and also as close to the bottom of the display as possible. Note: The location of the dip left to right is referred to as the “tune” and the depth of the dip (closeness to the baseline) is referred to as the “match.” The tune screw will tend to move the dip left–right and the match screw will improve the depth of the dip. The display on the preamp housing also shows the quality of the probe tuning and can be used in conjunction with or instead of the computer screen display. 5. When the tuning is OK, type halt to stop the wobble routine. 6. Restart sample spinning if desired. Leave spinning off for 2D experiments (Figure A1.2-1).</p>\r\n","source-26":"<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-026-fig-1.webp\" alt=\"Figure from source page 26.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure A1.2-1 Probe tuning display (wobb command) of an arbitrary probehead. Dotted vertical line is the resonance frequency of the nucleus to be tuned. Solid red line: proper tuning has been achieved; solid black line: both tuning and matching are not correct.</p>\r\n<h3>Spectrometer Setup—X-Nucleus Tuning</h3>\r\n<p>1. Carry out steps 1–6 above to ensure the 1H coil is tuned. 2. Use the edc or re command to create a new or read an existing dataset. 3. Use the rpar command to read the correct parameter set for the X-nucleus you want to observe, then type ii to initialize the spectrometer. 4. Type acqu to go to the acquisition window, then type wobb or cwobb (the latter for some systems with cryoprobes) to start the probe tuning (“wobble”) routine.</p>\r\n<p>Tuning the X-nucleus coil—broadband-type probes (BBO, BBFO, BBI, TBI, etc.)</p>\r\n<p>5. X-nucleus coil tuning is done using gold-colored sliders visible on the bottom of the probe. The sliders are numbered, and there is a directory of numbers for the tune and match settings for most common X-nuclei hanging below the probe. Confirm that the tune and match settings are correct for the X-nucleus you want to observe. 6. The computer screen will show a trace with a dip in it; hopefully the dip will be close to the correct frequency in the center of the screen. If there is no dip, click the WOBB-SW button to the left of the screen, then enter a new value in the correct field of the screen that pops up. The default SW is 4 MHz; try 12 or 16 MHz if it needs changing.</p>\r\n","source-27":"<p>7. When you have confirmed that there is a dip present, go to the magnet and adjust the gold tune and match sliders under the probe to bring the minimum of the dip to the center of the screen and also as close to the bottom of the display as possible. Note: The location of the dip left to right is referred to as the “tune” and the depth of the dip (closeness to the baseline) is referred to as the “match.” The tune slider(s) will tend to move the dip left–right and the match slider(s) will improve the depth of the dip. The display on the preamp housing also shows the quality of the probe tuning and can be used in conjunction with, or instead of, the computer screen display. 8. When the tuning is OK, type halt to stop the wobble routine. 9. Be sure to tune the X-nucleus coil back to C13 before you leave the spectrometer.</p>\r\n<p>Tuning the 13C (and 15N, Chapter 6) coils—,TXI or QXI-type probes</p>\r\n<p>5. Proceed as above for H1 tuning, using the blue tune and match screws for tuning 13C and the red tune and match screws for tuning 15N (check first that these colors apply for your probe). 6. When the tuning is OK, type halt to stop the wobble routine. 7. Restart sample spinning if desired. Note: if your spectrometer has a QNP probe, consult with your spectrometer administrator prior to attempting any tuning of the X-nucleus coil.</p>\r\n<h3>Probe Tuning—Using ATMM or ATMA Routine</h3>\r\n<p>The</p>\r\n<p>routine uses remote motor control to tune the probe so the operator does not have to physically manipulate the probe tuning controls at the probe.</p>\r\n<h3>ATMM/ATMA</h3>\r\n<h3>ATMM</h3>\r\n<p>allows the operator to manually control the tuning and matching operation with a software interface, while ATMA carries out the process automatically.</p>\r\n<p>1. After the desired experiment is set up, type atmm to start the probe tuning routine. If you are planning on running several experiments on the same sample, for probe tuning be sure to first set up the experiment which uses all the different nuclei which you will be measuring.</p>\r\n","source-28":"<p>2. A wobb window will appear along with an atmm interface window. Click the arrow buttons in the TUNE and MATCH fields in the atmm window to optimize the probe tuning and matching as displayed in the wobb window. 3. Multinuclear experiments will result in a button being displayed in the atmm window for each active nucleus. Tune all relevant nuclei going from lowest frequency to highest. Click each nucleus button in turn to tune for that nucleus. 4. When all tuning is complete exit atmm using the File tab pulldown. 5. If your NMR facility or specific spectrometer uses only automated probe tuning, the command atma will start the automated process. You will still get a glimpse of the tuning curve(s) during the operation, similar to what you see when using atmm.</p>\r\n<h3>APPENDIX 1.3 QUININE SPECTRA</h3>\r\n<p>See Figures A1.3-1 and A1.3-2.</p>\r\n<h3>APPENDIX 1.4 LINESHAPE EFFECTS OF NONSPINNING SHIMS</h3>\r\n<p>See Figure A1.4.</p>\r\n<h3>APPENDIX 1.5 PULSE WIDTH CALIBRATION WITH PAROPT</h3>\r\n<p>The au program paropt provides the automation of the parameter optimization process. To carry out the p90 pulse width determination, proceed as follows. We assume here that a normal 1H acquisition has just been completed as in Part 1, steps 1–3.</p>\r\n<p>1. Confirm the current dataset is set up for observe-pulse calibration or adjust as necessary, typically with NS = 1, DS = 0, D1 = a long delay (ca. 12 s for <sup>1</sup>H), PL1 = the normal value for your spectrometer, and phase correction set. Reduce the current RG value by ca. 50%. Make sure the pulse sequence in use (PULPROG) does not include the text “30” in its title; e.g., use PULPROG = zg, not zg30. Note that whatever plot region is defined now (F1P and F2P in edp) will be used when paropt displays the spectra, so alter it if necessary. 2. The following example will be approximately correct for an initial survey <sup>1</sup>H p90 calibration on most spectrometers.</p>\n","source-29":"<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-029-fig-1.webp\" alt=\"Figure from source page 29.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure A1.3-1 500 MHz 1H spectrum of quinine hydrochloride in CDCl3 at 298 K.</p>\r\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-029-fig-2.webp\" alt=\"Figure from source page 29.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure A1.3-2 125 MHz 13C spectrum of quinine hydrochloride in CDCl3 at 298 K.</p>\r\n","source-30":"<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-030-fig-1.webp\" alt=\"Figure from source page 30.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure A1.4 (a) Impact of various nonspinning shims upon the observed lineshape of the residual solvent signal from a CDCl3 sample obtained using a Bruker Avance 500 MHz spectrometer equipped with a BBO probe and no sample spinning. The various shim conditions are: optimized (A); X shim is reduced (B) or increased (C) by 50; Y shim is reduced (D) or increased (E) by 50; XZ shim is reduced (F) or increased (G) by 500; YZ shim is reduced (H) or increased (I) by 500; XY shim is reduced (J) or increased (K) by 1000; X2 2 Y2 shim is reduced (L) or increased (M) by 1000. (b) Impact of various nonspinning shims upon the observed lineshape and spinning sidebands of the residual solvent signal from a CDCl3 sample obtained on a Bruker Avance 500 MHz spectrometer equipped with a BBO probe, with 20 Hz sample spinning. For clarity and compared to Figure A.4(a), the vertical display is increased by 10 times. The shim conditions are: optimized (A) with a small spinning sideband (marked by ×); X shim is increased by 500 (B); XZ shim is increased by 2000 (C); XY shim is increased by 10,000 (D); X2 2 Y2 shim is reduced by 10,000 (E).</p>\r\n","source-31":"<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-031-fig-1.webp\" alt=\"Figure from source page 31.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure A1.4 (Continued)</p>\r\n","source-32":"<p>Type paropt to start the program. In sequence four windows will popup requesting input:</p>\r\n<p>“Enter parameter to modify:” p1 then click “ok” “Enter initial parameter value:” 5 (µs) then click “ok” “Enter parameter increment:” 5 (µs) then click “ok” “Enter # of experiments:” 12 then click “ok” 3. The spectrometer now acquires 12 spectra with P1 values of 5–60 µs in steps of 5 µs. 4. When finished all 12 spectra will be displayed end-to-end in procno 999 of the current experiment, along with a message window indicating paropt is finished and which P1 value resulted in the maximum signal intensity (Figure A.5). Keep in mind that we are looking for the P1 corresponding to the second null in the spectra display, which is the 360° pulse, and not the maximum intensity.</p>\r\n<figure class=\"figure source-figure\"><img src=\"../assets/figures/page-032-fig-1.webp\" alt=\"Figure from source page 32.\" loading=\"lazy\"></figure>\r\n<p class=\"figure-caption\">Figure A1.5-1 Display of a completed paropt run obtained using the 1H spectrum of the 0.1% ETB sample at 800 MHz. This shows p1 varying from 5 µs to 40 µs in steps of 5 µs (8 spectra). Note the cursor line denoting the approximate break between the first spectrum displayed and the second one adjacent. From this display we can discern that the p360 is somewhere between 35 and 40 µs, and further that it is much closer to 35 µs than to 40. Further investigation confirmed a p90 of 8.9 µs.</p>\r\n","source-33":"<p>5. When finished with the paropt display type rep 1 to return to procno 1 of the current dataset. 6. Repeat as necessary with appropriately adjusted initial and incremental parameter values to home in on the precise p360. Always return to procno 1 before restarting paropt.</p>\r\n<p>There is another program, popt, which does parameter optimization using a parameter input window with additional options and the ability to optimize multiple parameters. If you are familiar with this it may be used instead of paropt. If you want to try using popt for the p360 determination, set the processing parameter PH_mod to “pk” prior to starting popt.</p>\r\n"},"chinese":{"source-11":"<h3>第 1 章</h3>\n<h3>基础知识与谱仪性能检查</h3>\n<h3>概述</h3>\n<p>本章的练习旨在介绍 NMR 数据采集与处理的一些基础知识。我们将深入了解匀场、脉冲校准、灵敏度检查以及数据采集与处理的若干细节。本章所涵盖的内容见 Claridge 一书的第 2 章和第 3 章。</p>\n<p>注意：对于每次实验课，我们建议新建一个实验名称，例如“chapter-1”，并为所运行的每个实验使用新的实验编号（expno）。切勿因意外覆盖数据而造成数据丢失！如有疑问，请始终在新的 expno 中运行实验。</p>\n<h3>样品与谱仪要求</h3>\n<p>本章练习将使用样品 A、B、C 和 D。由于本章的 NMR 实验均为简单的一维采集，因此对谱仪硬件没有特殊要求。</p>\n<h3>实验内容</h3>\n<h3>第 1 部分——熟悉操作</h3>\n<p>1. 使用不同的实验编号，按照谱仪的标准参数集和操作流程，分别建立 <sup>1</sup>H 和 <sup>13</sup>C 数据集（作者所在实验室采用的标准参数集的说明与示例见附录 1.1）。</p>\n<p>《实用 NMR 波谱学实验室指南：Bruker 谱仪的使用》。DOI：http://dx.doi.org/10.1016/B978-0-12-800689-4.00001-X © 2016 Elsevier Inc. 保留所有权利。</p>\n","source-12":"<p>2. 将奎宁/CDCl3 样品装入磁体，完成锁场和匀场。将探头调谐至 1H 和 13C（命令为 wobb、cwobb 或 atmm/atma；有关探头调谐的讨论，见附录 1.2）。如果您不熟悉探头调谐，请在此步骤中向谱仪管理员寻求帮助。请注意，每当更换样品或观测新的核种时，都应进行探头调谐，即使正文中没有明确提及。3. 采集数据，使用手动相位校正处理谱图，并检查化学位移定标。编辑标题文本（Title 选项卡或 setti），使其反映所用实验和样品。4. 绘制两张谱图；对于 1H 谱，应包括寻峰和积分。检查积分值是否合理。5. 分别使用 ef 和 ft 处理数据，观察指数加窗的影响。尝试不同的 lb 值，评估不同指数加窗函数对谱图的影响。6. 以图 1.1 为指导，尝试使用几种不同的窗函数（如高斯窗和正弦钟窗）处理 1H 数据。使用 wm 命令选择窗函数。在弹出窗口的下拉菜单中选择所需窗函数，然后在相应字段中输入必要的控制参数：高斯窗使用 gb 和 lb，正弦钟窗使用 ssb。建议的参数初始值如下：</p>\n<p>gb 0.3（范围为 0–1）</p>\n<p>lb 20.5（近似值约为 2 (1/AQ)）</p>\n<p>ssb 1 或 2（1 表示正弦钟窗，2 表示余弦窗）</p>\n<p class=\"figure-caption\">图 1.1 三种常用的数据处理窗函数，横轴表示单位采集时间：指数窗（实线）、高斯-指数窗（点线）和相移 45° 的正弦钟窗（虚线）。</p>\n","source-13":"<p>要将窗函数应用于原始 NMR 数据（自由感应衰减，FID），请单击弹出窗口中的 OK 按钮。然后使用 ft 或 fp 命令生成新谱图（fp 使用处理参数 PHC0 和 PHC1，将先前确定的相位校正应用于谱图；ft 则生成未经相位校正的谱图）。可随意尝试其他窗函数——原始 FID 保持不变，改变的只是谱图。7. 至少打印三张采用不同处理函数得到的谱图，并显示处理函数影响最明显的谱图区域。8. 附录 1.3 给出了奎宁在 500/125 MHz 下的 1H 和 13C 谱图示例。</p>\n<h3>第 2 部分——匀场与线形</h3>\n<p>1. 将奎宁样品更换为 CHCl3/acetone-d6 样品。锁场前，观察锁场显示中的信号：为什么看不到锁信号的摆动？2. 创建新数据集（edc 或 new 命令），锁定 acetone-d6，并确保样品旋转已开启。3. 手动调节 Z1、Z2 和 Z3 匀场（可使用 BSMS 实体键盘，或用 bsmsdisp 命令显示软件匀场界面），以获得最佳锁信号水平。保持较低的锁功率，以避免锁信号饱和（饱和的锁信号即使在匀场值未改变时也可能上下漂移，并且对匀场调整的响应可能低于正常水平）。4. 使用标准参数在新数据集中采集 1H 谱。与常规做法不同，将该谱图中 CHCl3 峰的化学位移设为 0，并将显示轴单位由 ppm 改为 Hz（上方图标栏中的 h/p 图标）。5. 使用 wrpa 和 re 命令（例如先执行 wrpa 3，再执行 re 3，将当前数据集复制到实验号 3 并载入），或使用 new 命令，将数据复制到新的 expno。优化 O1、SW 和 TD 参数，使数据（FID）采集时间 AQ 约为 10 s，以确保所得谱图具有足够的数字分辨率。将 SI 参数设为 TD/2，或检查其是否等于 TD/2。重新采集谱图并仔细观察 CHCl3 峰。将 CHCl3 峰周围约 ±30 Hz 的谱区放大，并将该放大区域定义为绘图区域。使用光标左键单击并拖动模式测量线宽</p>\n","source-14":"<p>和线形：在线峰半高处测量线宽；在线峰总高度的 0.55% 和 0.11% 处测量线形（即“裙部”）。记录测量结果。然后输入 humpcal，使用 au 程序中的峰拟合例程进行相同测量。结果是否符合技术指标？请注意，线形技术指标取决于所用仪器和探头，因此需要查阅仪器文档或咨询谱仪管理员。如果两者都无法方便地获得，对于常规探头，可参考以下合理指标：半高线宽小于 0.8 Hz；在 0.55% 和 0.11% 高度处测得的线形宽度分别小于 7.0 和 14.0 Hz。手动测量线宽时，可将 cy 设为 100 或 1000；例如，在 0.55% 高度处测量线宽时，光标高度读数将分别为 0.55 或 5.5 cm。请注意，如果显示的缩放区域过窄，光标可能无法显示其所在位置的正确高度值。通常可通过扩大显示的缩放区域（即增加显示范围所包含的 Hz 数）来解决。图 1.2 给出了线形测量示例。6. 继续调整匀场以改善线形。如果线形不对称，需要调整 Z2 和 Z4；同时检查 Z3 和 Z5。如果改变了 Z4，应重新调节 Z1、Z2 和 Z3。一个常用策略是先将 Z4 改变 500 个单位，重新匀场，然后观察谱图，判断线形是否改善。如果有所改善，则沿同一方向再改变 Z4 500 个单位并重复上述过程，直至获得最佳线形。如果线形变差，则从首次改变前的数值向相反方向改变 500 个单位，重新匀场并重新采集。</p>\n<p>如果改变了 Z5，应先重新调节 Z1 和 Z3，再调节 Z2。图 1.3 展示了部分 Z 轴（旋转）匀场项对线形的影响。7. 根据需要重新采集谱图。8. 关闭样品旋转，并按以下顺序优化低阶非旋转匀场项：a. Z1、X、XZ、XZ2；b. Z1、Y、YZ、YZ2。</p>\n<p>c. XY、X2−Y2、XZY；d. X、Y。请注意，在某些配备“矩阵”匀场系统的谱仪上，使用实体键盘调节非旋转匀场项时，需要先选择</p>\n","source-15":"<p>先按 X、Y、XY 或 X<sup>2</sup> − Y<sup>2</sup> 按钮，再选择所需的 Z 功能。例如，调整 X 匀场项时先按 X 按钮，再按 Z0 按钮；调整 YZ2 匀场项时先按 Y 按钮，再按 Z2 按钮，依此类推。附录 1.4 展示了部分非旋转匀场项对线形的影响。</p>\n<p class=\"figure-caption\">图 1.2　在配备 TXI 探头的 Bruker AV-III 800 MHz 谱仪上，于 298 K 记录的 0.1% CHCl<sub>3</sub>/acetone-d<sub>6</sub> 样品 <sup>1</sup>H 线形测试。使用 humpcal 测得非旋转条件下的半高线宽，以及 0.55% 和 0.11% 峰高处的线宽，分别为 0.58、5.6 和 11.8 Hz。图中还显示了线宽及约 0.55% 峰高处线宽的手动测量。谱图窗口左侧光标信息区显示“Value = 0.56 rel”；该值是光标所在数据点高度相对于峰高（cy）的数值，cy 已设为 100 cm。手动测量线形时，若不能恰好取到 0.55% 的高度，可使用非常接近的高度，或在相邻数据点之间插值。峰底部可见由地面振动引起的低频（约 10 Hz）噪声。</p>\n<p>9. 重新开启样品旋转，并微调 Z1、Z2 和 Z3；重新采集谱图。判断结果是否足够理想，若仍不理想，则再次重复匀场过程。10. 在开启旋转的条件下采集最后一张、也是最佳的一张谱图。处理并绘图，在打印谱图的标题中注明线形测量结果和旋转状态。所得线形是否达到技术指标？</p>\n","source-16":"<p class=\"figure-caption\">图 1.3 各匀场项对所观察线形的影响。样品为 CDCl3，以残余溶剂信号进行观察；谱图在配备 BBO 探头的 Bruker Avance DRX 500 MHz 谱仪上获得，样品不旋转。各匀场条件为：已优化（A）；Z 匀场值减小 20（B）或增大 20（C）；Z2 匀场值减小 100（D）或增大 100（E）；Z3 匀场值减小 500（F）或增大 500（G）；Z4 匀场值减小 4000（H）或增大 4000（I）。</p>\n<p>11. 关闭样品旋转，在新的 expno 中重新采集谱图。打印该谱图，并再次在标题中注明线形信息和旋转状态。12. 使用 wsh 命令保存匀场设置（例如 wsh chapter1-acet.shm）。</p>\n","source-17":"<h3>第 3 部分——1H 脉冲校准与灵敏度</h3>\n<p>1. 为使谱仪获得最高灵敏度，需要优化多个方面。将 0.1% 乙苯样品放入磁体，开启旋转，以 CDCl3 锁场并匀场。使用新的 expno。将探头调谐至 1H，使用标准参数采集 1H 谱。2. 将脉冲程序（PULPROG）设为 zg，NS = 1，DS = 0，P1 = 3 µs。检查发射功率电平（参数 PL1）是否为适用于本谱仪的正确值。如果无法方便地获得该信息，通常可采用 0 dB 的功率电平。使用 rga 检查接收增益。重新采集并校正相位。注：按照 Bruker 的约定，更大的正功率电平（dB）数值表示更低的 RF 功率。例如，0 dB 通常是中等偏高的功率，而 120 dB 则是很低（接近零）的功率。因此，PL 值表示相对于参考功率电平的衰减（功率降低）量。3. 复制数据并使用新的 expno。现在用 360° 法确定 90° 脉冲（p90）长度。360°</p>\n<p>脉冲产生的信号几乎为零；小于 360° 时产生较弱的负峰，大于 360° 时产生较弱的正峰。将 P1 设为所用探头规定的 p90 值的大约四倍（典型的 1H 高功率脉冲长度预计约为 10 µs）。重新采集并应用已有的相位校正（efp）。调整 P1 值并重新采集数据，直至所得谱图的信号强度接近零。p90 值等于此时的 P1 除以 4。也可使用名为 paropt 的自动例程执行这一过程，其用法见附录 1.5（图 1.4）。4. 复制数据并使用新的 expno。将 P1 设为上面确定的 p90 值；用 rga 检查接收增益设置后，采集一次扫描。仔细校正所得谱图的相位。5. 使用新的 expno。按如下设置采集和处理参数：D1 = 60 s，O1P = 4 ppm，SW = 10 ppm，TD = 32K（即 32768 个点），LB = 1.0，SI = 16K。务必输入经校准的 p90 参数（P1）。重新采集一次扫描，使用 ef 处理，并测定信噪比。最简便的方法是使用 sinocal 程序。输入 sinocal 启动例程，随后程序会要求输入若干参数。信号区选择亚甲基四重峰，范围定义为 2.8–2.5 ppm；噪声区定义为 7.1–2.8 ppm；噪声宽度输入 200 Hz 所对应的 ppm 值（在 500 MHz 下即 0.4 ppm）。打印该谱图，并在标题文本中注明 s/n 值（图 1.5）。</p>\n","source-18":"<p class=\"figure-caption\">图 1.4 360° 脉冲校准：通过改变共振脉冲激发的持续时间并观察脉冲后的信号来进行校准。360° 脉冲对应第二个零点；其一半对应第一个零点，而 360° 的 1/4 或 3/4 对应最大的正信号或负信号。</p>\n<p class=\"figure-caption\">图 1.5 使用配备 TXI 探头的 Bruker AV-III 800 MHz 谱仪，在 297 K 下测得 0.1% ETB 样品（20 Hz 旋转）的 1H 信噪比为 2150:1。该比值以亚甲基峰高除以谱图中 200 Hz 宽随机噪声区的 RMS 噪声电平的两倍计算。</p>\n","source-19":"<p>6. 可选。在执行步骤 7–9 之前，请先获得谱仪管理员的许可。7. 在新的 expno 中创建新数据集。使用探头调谐例程，将探头失谐，使调谐凹陷偏离正确的 1H 频率约 1 MHz。8. 重复 p90 校准过程。9. 使用新的 expno。采用新的 p90 校准值重复灵敏度测试扫描，对所得谱图运行 sinocal 并打印谱图。该结果与步骤 5 所得结果是否不同？为什么相同或不同？</p>\r\n<h3>第 4 部分——13C 脉冲校准与灵敏度</h3>\r\n<p>1. 放入 10% ETB 样品，开启旋转，以 CDCl3 锁场并匀场。建立新的 expno。2. 采集 1H 谱，检查匀场是否合格。3. 使用标准参数设置 13C 采集。这里假定标准参数中的 PL1 值正确。4. 检查探头在 1H 和 13C 两个通道上的调谐。5. 以 8 次扫描采集一张 13C 谱，检查谱图是否正常。6. 将数据复制到新的 expno，并设置</p>\r\n<h3>DS = 0，</h3>\r\n<h3>NS = 1，</h3>\r\n<p>PULPROG = zgpg，P1 = 5 µs。运行实验，并仔细校正谱图相位。7. 按照第 3 部分所述方法确定 13C p90。在两次采集之间设置足够长的 D1 延迟（30–60 s），以免信号饱和。8. 将数据复制到新的 expno，并按如下参数设置带 1H 去耦的 13C 灵敏度测试：</p>\r\n<h3>PULPROG</h3>\r\n<p>zgdc</p>\r\n<h3>RG</h3>\r\n<p>本谱仪的最大值（或接近最大值）</p>\r\n<h3>D1</h3>\r\n<p>300 s</p>\r\n<h3>O1P</h3>\r\n<p>80 ppm</p>\r\n<h3>SW</h3>\r\n<p>200 ppm</p>\r\n<h3>P1</h3>\r\n<p>正确的 p90 值</p>\r\n<h3>TD</h3>\r\n<p>256K</p>\r\n<h3>O2P</h3>\r\n<p>约 5 ppm（即 ETB 1H 谱的大致中心）</p>\r\n<h3>CPDPRG2</h3>\r\n<p>waltz16</p>\r\n<h3>PCPD2</h3>\r\n<p>使用本谱仪标准 13C 参数中的值</p>\r\n<h3>PL12</h3>\r\n<p>使用本谱仪标准 13C 参数中的值</p>\r\n<h3>LB</h3>\r\n<p>0.3</p>\r\n<h3>SI</h3>\r\n<p>128K</p>\r\n","source-20":"<p>注：PCPD2/PL12 参数组合用于校准约 80 µs（500 MHz 谱仪）至 60 µs（800 MHz 谱仪）的 1H p90。该脉冲作为 waltz16 复合脉冲去耦序列（CPDPRG2）的一部分，用于在整个 1H 谱宽范围内实现均匀的 1H 去耦。重新采集一次扫描，处理数据并测定信噪比。运行 sinocal 例程并输入以下参数：信号区为 130–125 ppm；噪声区为 125–29 ppm；噪声宽度为 40 ppm。打印该谱图，并在标题文本中注明 s/n 值。</p>\n<h3>第 5 部分——在 TopSpin 中查看和编辑文本文件</h3>\n<p>1. 宏、au 程序和脉冲程序都是谱仪日常操作中会用到的文本文件类型。用于计算信噪比的 sinocal 程序就是一个 au 程序。能够查看甚至编辑这些类型文件的自有副本通常很有用。以下步骤将逐一介绍这些文件类型。2. 宏是包含一系列按顺序执行的 TopSpin 命令的文件。输入 edmac，打开软件自带宏的菜单。下面以编辑一个可自动采集和处理数据的自定义宏为例。输入 edmac zgefp.xyz（其中 xyz = 您姓名的首字母缩写），然后按回车键，进入名为“zgefp.xyz”的新宏编辑模式。在编辑窗口中按如下内容输入：</p>\n<p>rga zg ef apk 不同 TopSpin 版本结束编辑过程的方式略有不同。对于 TopSpin 1.3，单击 edmac 窗口左下角的 OK 按钮（或输入 alt-o），保存宏并退出编辑器。对于 TopSpin 2.x 版本，打开 File 下拉菜单并选择 Close，然后在弹出窗口中确认保存请求并退出编辑器。以后只需输入 zgefp.xyz，即可依次执行宏中输入的各条命令。3. Au 程序可在谱仪或数据上运行。这里我们将创建一个 au 程序的版本，该程序</p>\n","source-21":"<p>我们实验室使用的这个程序称为“standard”。它用于在有人使用完谱仪后，将装有标准 CDCl3 样品的谱仪恢复到待用状态。该程序假定当前已载入一个 <sup>1</sup>H 数据集。输入 edau standard.xyz（同样，xyz = 你的姓名首字母）可打开 au 程序编辑器，并新建名为 standard.xyz 的文件。在编辑器窗口中输入以下文本：</p>\n<p>/*file location: /opt/topspin/exp/stan/nmr/au/src/standard.xyz */</p>\n<p>/*this program will read shim file shims.probe and lock on CDCl3</p>\n<p>solvent */</p>\n<p>/*this program should be executed from a 1H dataset which DOES NOT</p>\n<p>contain critical data*/</p>\n<p>char solvent[20]; /*initialize the character variable named ‘solvent’ */</p>\n<p>/*load the current dataset */ FETCHPAR(“SOLVENT”, solvent) /*save the current solvent value into ‘solvent’ */ STOREPAR(“SOLVENT”, “CDCl3”) /*set the solvent variable to CDCl3 */ RSH(“shims.probe”) /*load the shims from file ‘shims.probe’ */</p>\n<h3>GETCURDATA</h3>\n<p>/*initialize interfaces */</p>\n<h3>II</h3>\n<p>/*set up lock for new solvent */</p>\n<h3>LOPO</h3>\n<p>/*lock on CDCl3 */ STOREPAR(“SOLVENT”, solvent) /*set solvent parameter back to original value */</p>\n<h3>LOCK</h3>\n<p>/*finish the au program */</p>\n<h3>QUIT</h3>\n<p>请注意，/* 与 */ 符号之间的文本是用于说明该 au 程序运行方式的注释，因此编辑 au 程序时可以不输入这些内容。如果将其写入程序，它们会被视为注释，不会作为程序的一部分编译。若要加入注释，务必正确使用标记符号（/* */）。不同版本的 TopSpin 结束编辑的方式略有不同。在 TopSpin 1.3 中，输入所有行后，单击编辑器窗口底部的 SAVE, EXIT, and COMPILE 按钮（或输入 alt-x），保存并编译程序，然后退出编辑器窗口。在 TopSpin 2 中，先单击 COMPILE 按钮编译程序，再打开 File 下拉菜单并选择 Close，然后在弹出窗口中确认保存请求以退出编辑器。假定编译成功，只需输入 standard.xyz 即可执行该程序。4. 输入 edpul，打开谱仪上所有脉冲程序的菜单。例如选择“zg”，再单击窗口底部的 EDIT 按钮将其打开。此时可看到一个简单脉冲程序的语法。此外，谱图窗口中的 PulseProg 选项卡会显示</p>\n","source-22":"<p>当前实验所用的脉冲程序。我们将在第 3 章的实验中编辑脉冲程序。</p>\n<h3>总结</h3>\n<p>实验报告应包括以下内容：</p>\n<p>1. 奎宁：三张 <sup>1</sup>H 谱，每张采用不同的窗函数处理，以及一张 <sup>13</sup>C 谱。2. 丙酮-d6 中的 0.3% CHCl3：样品旋转与不旋转时的线形谱，并在标题文本中写明结果。3. 0.1% ETB 样品：<sup>1</sup>H 谱、显示约 360° 脉冲的谱，以及灵敏度谱，并在标题文本中写明结果。4. 10% ETB 样品：标准 <sup>13</sup>C 谱和灵敏度谱，并在标题文本中写明结果。5. 建议思考的问题：a. 90° 脉冲有何意义？b. 将线形样品放入磁体后，为什么锁场窗口中没有像更换为另一支 CDCl3 样品时那样出现锁场摆动信号？</p>\n<p>c. 第一张线形样品谱中的残余溶剂峰为什么呈现这种形状？为什么会显示这种特定的多重峰型？</p>\n<p>d. 能否对奎宁的 <sup>1</sup>H 和 <sup>13</sup>C 谱作出初步归属？</p>\n<p>e. 如果在失谐探头后测量了 <sup>1</sup>H 灵敏度（选做），两次结果为何不同？是否观察到与灵敏度变化相关的线形变化？</p>\n<h3>附录 1.1 标准参数集</h3>\n<p>在本书中，“标准参数”是指在典型有机样品上获得常规一维 <sup>1</sup>H 或 <sup>13</sup>C 谱时所用的参数，即最基本的 NMR 实验设置。与 NMR 数据采集有关的参数包括 RF 脉冲宽度和脉冲功率、精确的谱仪频率（或发射机偏移）、谱宽、采集的数据点数以及脉冲间延迟（或弛豫延迟）。对于 <sup>13</sup>C 采集，还包括 <sup>1</sup>H 去耦参数，例如</p>\n","source-23":"<p>RF 功率、去耦脉冲宽度、去耦脉冲程序以及去耦通道的发射机偏移。参数集还包括所需的数据处理参数，例如施加于 FID 的窗函数类型及其设置、最终谱图中的实数数据点数和化学位移定标信息。</p>\n<p>Bruker TopSpin 软件包含大量参数集，通常会在谱仪首次安装时随软件一并安装。用于常规</p>\n<p>一维 <sup>1</sup>H 和 <sup>13</sup>C 观测的参数集分别名为 PROTON 和 C13CPD。不过，这些参数集不能直接使用，因为默认情况下并不包含特定谱仪与探头组合所需的脉冲校准信息。还必须使用 getprosol 命令，从“prosol”（探头与溶剂信息）表中载入正确的脉冲校准信息。</p>\n<h3>一维</h3>\n<p>操作如下：</p>\n<p>rpar PROTON all　载入 PROTON 参数集及其全部子集<br>getprosol　用正确的校准信息更新采集参数</p>\n<p>请注意，要使上述操作正确执行，必须使用 edhead 命令正确设置“probe”变量，并正确配置 prosol 表。附录 4.1 给出了 prosol 表的示例。</p>\n<p>作者所在实验室采用另一种方式：在每台谱仪上，针对每种常用探头建立并保存定制参数集。这些参数集包含所有相关校准信息，因此用户只需在采集数据之前载入正确的参数集，如下所示：</p>\n<p>rpar h1.cryo all　载入使用冷冻探头进行 <sup>1</sup>H 观测的本地参数集</p>\n<p>标准参数集的具体设置会随谱仪和探头而有所不同。以下示例来自作者所在实验室的一台 Bruker Avance DRX-500 谱仪，该谱仪配有 5 mm TXI 冷冻探头。</p>\n","source-24":"<p><sup>1</sup>H 标准参数（参数集 h1.cryo）</p>\n<h3>PULPROG:</h3>\n<p>zg30</p>\n<h3>32K (K = 1024)</h3>\n<h3>TD:</h3>\n<h3>NS:</h3>\n<p>8</p>\n<h3>DS:</h3>\n<p>2</p>\n<h3>SWH:</h3>\n<p>6510.40 (Hz, ca. 13 ppm)</p>\n<h3>AQ:</h3>\n<p>2.52 s</p>\n<h3>RG</h3>\n<p>使用 rga 设置，或针对每个样品手动优化</p>\n<h3>D1:</h3>\n<p>1.00 s</p>\n<h3>NUC1:</h3>\n<h3><sup>1</sup>H</h3>\n<p>8.0 µs</p>\n<h3>P1:</h3>\n<p>(+)1.6 dB</p>\n<h3>PL1:</h3>\n<h3>SFO1:</h3>\n<p>499.89250 MHz</p>\n<h3>O1 (O1P):</h3>\n<p>2500 Hz (ca. 5.0 ppm)</p>\n<h3>SI:</h3>\n<p>16k</p>\n<h3>LB:</h3>\n<p>0.3 (Hz)</p>\n<p><sup>13</sup>C 标准参数（参数集 c13.cryo）</p>\n<h3>PULPROG:</h3>\n<p>zgpg30</p>\n<h3>TD:</h3>\n<p>32k</p>\n<h3>NS:</h3>\n<p>256</p>\n<h3>DS:</h3>\n<p>8</p>\n<h3>SWH:</h3>\n<p>30303.03 (Hz, ca. 240 ppm)</p>\n<h3>AQ:</h3>\n<p>0.54 s</p>\n<h3>RG</h3>\n<p>通常设为谱仪的最大值（或接近最大值）</p>\n<h3>D1:</h3>\n<p>2.00 s</p>\n<h3>NUC1:</h3>\n<h3><sup>13</sup>C</h3>\n<p>16.0 µs</p>\n<h3>P1:</h3>\n<p>−3 dB</p>\n<h3>PL1:</h3>\n<h3>SFO1:</h3>\n<p>125.71124 MHz</p>\n<h3>O1 (O1P):</h3>\n<p>13,800 Hz (ca. 110 ppm)</p>\n<h3>CPDPRG2:</h3>\n<p>waltz16</p>\n<h3>NUC2:</h3>\n<h3><sup>1</sup>H</h3>\n<p>80.0 µs</p>\n<h3>PCPD2:</h3>\n<h3>PL2</h3>\n<p>120 dB</p>\n<h3>PL12:</h3>\n<p>21.0 dB</p>\n<h3>PL13:</h3>\n<p>24.0 dB</p>\n<h3>SFO2:</h3>\n<p>499.89200 MHz</p>\n<h3>O2 (O2P):</h3>\n<p>2000 Hz (ca. 4.0 ppm)</p>\n<h3>SI:</h3>\n<p>16k</p>\n<h3>LB:</h3>\n<p>3.0 (Hz)</p>\n","source-25":"<h3>附录 1.2 探头调谐</h3>\n<p>如果以前没有进行过探头调谐，请先请谱仪管理员或其他合格人员协助，再尝试以下操作。</p>\n<p>注意：如果探头配有电机控制的调谐与匹配装置，请跳至本附录末尾“使用 ATMM 或 ATMA 程序调谐探头”一节。</p>\n<h3>调谐 <sup>1</sup>H 线圈——所有探头</h3>\n<p>1. 首先调谐 <sup>1</sup>H 线圈。关闭样品旋转，并建立一个 <sup>1</sup>H 数据集。2. 输入 acqu 进入采集窗口，然后输入 wobb 或 cwobb（后者用于某些配有冷冻探头的系统），启动探头调谐（“wobble”）程序。3. 计算机屏幕上会显示一条带有凹谷的曲线；理想情况下，凹谷应接近屏幕中央的正确频率。如果没有凹谷，单击屏幕左侧的 WOBB-SW 按钮，并在弹出窗口的相应字段中输入新值。默认 SW 为 4 MHz；如需更改，可尝试 12 或 16 MHz。4. 确认存在凹谷后，前往磁体处，调节探头下方带黄色标记的 tune 和 match 螺钉（螺钉头可能较大或较小；不要将其与通常呈黄铜色的探头安装螺钉混淆），使凹谷最低点移至屏幕中央，并尽可能接近显示区底部。注意：凹谷的左右位置称为“tune”，凹谷的深度（接近基线的程度）称为“match”。tune 螺钉主要使凹谷左右移动，match 螺钉则改善凹谷深度。前置放大器外壳上的显示器也会显示探头调谐质量，可与计算机屏幕配合使用，也可代替计算机屏幕。5. 调谐完成后，输入 halt 停止 wobble 程序。6. 如有需要，重新启动样品旋转。二维实验应保持样品不旋转（图 A1.2-1）。</p>\n","source-26":"<p class=\"figure-caption\">图 A1.2-1 任意探头的调谐显示（wobb 命令）。垂直虚线为待调谐核的共振频率。红色实线：已正确调谐；黑色实线：调谐和匹配均不正确。</p>\n<h3>谱仪设置——X 核调谐</h3>\n<p>1. 执行上述步骤 1–6，确保 <sup>1</sup>H 线圈已调谐。2. 使用 edc 或 re 命令新建数据集或读取已有数据集。3. 使用 rpar 命令读取待观测 X 核的正确参数集，然后输入 ii 初始化谱仪。4. 输入 acqu 进入采集窗口，再输入 wobb 或 cwobb（后者用于某些配有冷冻探头的系统），启动探头调谐（“wobble”）程序。</p>\n<p>调谐 X 核线圈——宽带型探头（BBO、BBFO、BBI、TBI 等）</p>\n<p>5. X 核线圈使用探头底部可见的金色滑块进行调谐。各滑块带有编号，探头下方还悬挂着一份编号对照表，列出了大多数常用 X 核的 tune 和 match 设置。确认待观测 X 核的 tune 和 match 设置正确。6. 计算机屏幕上会显示一条带有凹谷的曲线；理想情况下，凹谷应接近屏幕中央的正确频率。如果没有凹谷，单击屏幕左侧的 WOBB-SW 按钮，并在弹出窗口的相应字段中输入新值。默认 SW 为 4 MHz；如需更改，可尝试 12 或 16 MHz。</p>\n","source-27":"<p>7. 确认存在凹谷后，前往磁体处，调节探头下方金色的 tune 和 match 滑块，使凹谷最低点移至屏幕中央，并尽可能接近显示区底部。注意：凹谷的左右位置称为“tune”，凹谷的深度（接近基线的程度）称为“match”。tune 滑块主要使凹谷左右移动，match 滑块则改善凹谷深度。前置放大器外壳上的显示器也会显示探头调谐质量，可与计算机屏幕配合使用，也可代替计算机屏幕。8. 调谐完成后，输入 halt 停止 wobble 程序。9. 离开谱仪前，务必将 X 核线圈重新调谐至 C13。</p>\n<p>调谐 <sup>13</sup>C（以及第 6 章中的 <sup>15</sup>N）线圈——TXI 或 QXI 型探头</p>\n<p>5. 按上述 <sup>1</sup>H 调谐方法操作：用蓝色 tune 和 match 螺钉调谐 <sup>13</sup>C，用红色 tune 和 match 螺钉调谐 <sup>15</sup>N（请先确认这些颜色标记适用于你的探头）。6. 调谐完成后，输入 halt 停止 wobble 程序。7. 如有需要，重新启动样品旋转。注意：如果谱仪配有 QNP 探头，在尝试调谐任何 X 核线圈前，请先咨询谱仪管理员。</p>\n<h3>使用 ATMM 或 ATMA 程序调谐探头</h3>\n<p>ATMM/ATMA</p>\n<p>程序通过远程电机控制来调谐探头，因此操作人员无需在探头处手动操作调谐控件。</p>\n<h3>ATMM/ATMA</h3>\n<h3>ATMM</h3>\n<p>允许操作人员通过软件界面手动控制调谐和匹配，而 ATMA 会自动完成这一过程。</p>\n<p>1. 设置好所需实验后，输入 atmm 启动探头调谐程序。如果计划在同一样品上运行多个实验，调谐探头时务必先设置会用到所有待测核种的实验。</p>\n","source-28":"<p>2. wobb 窗口会与 atmm 界面窗口同时出现。单击 atmm 窗口中 TUNE 和 MATCH 字段内的箭头按钮，根据 wobb 窗口中的显示优化探头的调谐与匹配。3. 对于多核实验，atmm 窗口会为每个启用的核显示一个按钮。按频率由低到高调谐所有相关核，并依次单击各核按钮进行调谐。4. 所有调谐完成后，通过 File 选项卡的下拉菜单退出 atmm。5. 如果所在 NMR 实验室或特定谱仪仅使用自动探头调谐，输入 atma 即可启动自动过程。运行期间仍可短暂看到调谐曲线，与使用 atmm 时类似。</p>\n<h3>附录 1.3 奎宁谱</h3>\n<p>见图 A1.3-1 和图 A1.3-2。</p>\n<h3>附录 1.4 非旋转匀场线圈对线形的影响</h3>\n<p>见图 A1.4。</p>\n<h3>附录 1.5 使用 PAROPT 校准脉冲宽度</h3>\n<p>au 程序 paropt 可自动执行参数优化过程。按照以下步骤测定 p90 脉冲宽度。这里假定已按第 1 部分步骤 1–3 完成一次常规 <sup>1</sup>H 采集。</p>\n<p>1. 确认当前数据集已设置用于观测脉冲校准，必要时进行调整。典型设置为 NS = 1、DS = 0、D1 = 较长延迟（<sup>1</sup>H 约 12 s）、PL1 = 谱仪的常规值，并且已设置相位校正。将当前 RG 值降低约 50%。确保所用脉冲程序（PULPROG）的名称中不含“30”；例如应使用 PULPROG = zg，而不是 zg30。请注意，paropt 显示谱图时会采用当前定义的绘图区间（edp 中的 F1P 和 F2P），因此必要时应先更改。2. 对于大多数谱仪，以下示例可近似用于 <sup>1</sup>H p90 初步扫描校准。</p>\n","source-29":"<p class=\"figure-caption\">图 A1.3-1 298 K 下，盐酸奎宁在 CDCl3 中的 500 MHz <sup>1</sup>H 谱。</p>\n<p class=\"figure-caption\">图 A1.3-2 298 K 下，盐酸奎宁在 CDCl3 中的 125 MHz <sup>13</sup>C 谱。</p>\n","source-30":"<p class=\"figure-caption\">图 A1.4　(a) 使用配有 BBO 探头的 Bruker Avance 500 MHz 谱仪，在样品不旋转条件下采集 CDCl3 样品的残余溶剂信号；不同非旋转匀场线圈对其线形的影响如下：优化状态 (A)；X 匀场减小 50 (B) 或增大 50 (C)；Y 匀场减小 50 (D) 或增大 50 (E)；XZ 匀场减小 500 (F) 或增大 500 (G)；YZ 匀场减小 500 (H) 或增大 500 (I)；XY 匀场减小 1000 (J) 或增大 1000 (K)；X2 − Y2 匀场减小 1000 (L) 或增大 1000 (M)。(b) 使用配有 BBO 探头的 Bruker Avance 500 MHz 谱仪，在样品以 20 Hz 旋转的条件下采集 CDCl3 样品的残余溶剂信号；不同非旋转匀场线圈对所观察线形及旋转边带的影响。为便于观察，与图 A1.4(a) 相比，纵向显示放大了 10 倍。匀场条件如下：优化状态 (A)，带有一个小的旋转边带（以 × 标记）；X 匀场增大 500 (B)；XZ 匀场增大 2000 (C)；XY 匀场增大 10,000 (D)；X2 − Y2 匀场减小 10,000 (E)。</p>\n","source-31":"<p class=\"figure-caption\">图 A1.4（续）</p>\n","source-32":"<p>输入 <code>paropt</code> 启动程序。随后会依次弹出四个窗口，要求输入以下内容：</p>\n<p>“Enter parameter to modify:”：输入 <code>p1</code>，然后单击“ok”；“Enter initial parameter value:”：输入 5（µs），然后单击“ok”；“Enter parameter increment:”：输入 5（µs），然后单击“ok”；“Enter # of experiments:”：输入 12，然后单击“ok”。3. 此时谱仪将采集 12 张谱图，P1 值从 5 至 60 µs，每次递增 5 µs。4. 完成后，12 张谱图会在当前实验的 <code>procno 999</code> 中首尾相接显示；同时会出现一个消息窗口，提示 <code>paropt</code> 已完成，并指出哪个 P1 值给出了最大信号强度（图 A1.5）。请注意，我们要找的是谱图显示中第二个零点所对应的 P1，即 360° 脉冲，而不是最大强度。</p>\n<p class=\"figure-caption\">图 A1.5-1　使用 800 MHz 下 0.1% ETB 样品的 ¹H 谱得到的已完成 <code>paropt</code> 运行的显示结果。图中 <code>p1</code> 从 5 µs 变化到 40 µs，步长为 5 µs（8 张谱图）。请注意光标线标出了所显示的第一张谱图与其相邻第二张谱图之间的大致分界。从该显示可判断，p360 在 35 至 40 µs 之间，且更接近 35 µs 而非 40 µs。进一步测定证实 p90 为 8.9 µs。</p>\n","source-33":"<p>5. 完成 <code>paropt</code> 显示后，输入 <code>rep 1</code>，返回当前数据集的 <code>procno 1</code>。6. 根据需要，适当调整初始参数值和递增参数值并重复操作，以逐步确定准确的 p360。重新启动 <code>paropt</code> 前，务必先返回 <code>procno 1</code>。</p>\n<p>另有一个程序 <code>popt</code>，它通过带附加选项的参数输入窗口进行参数优化，并可优化多个参数。若你熟悉该程序，可用它代替 <code>paropt</code>。若要尝试用 <code>popt</code> 测定 p360，请在启动 <code>popt</code> 前将处理参数 <code>PH_mod</code> 设为“pk”。</p>\n"},"figurePlacements":{"source-11":[{"source":0,"before":"第1部分 家庭化"}],"source-12":[{"source":0,"before":"图 1.1 图表:以单位采集时间的水平轴绘制了常用的数据处理窗口函数:指数式 (固体线);高斯指数式 (点线); 45°转移的弦 (线)."}],"source-15":[{"source":0,"before":"图 1.2"}],"source-16":[{"source":0,"before":"图1.3 根据布鲁克Avance DRX 500 MHz谱仪采用BBO探测器,无样本旋转的CDCl3样本的残余溶剂信号对观察到的线形的影响.各种光谱条件是:优化"}],"source-18":[{"source":0,"before":"图1.4 360°脉冲校准,基于在变长度在共振脉冲激励后的信号观察. 360°脉冲是第二个零点:其中一半导致第一个零点,而1"},{"source":1,"before":"图1.5 1H信号与噪音比分为2150:1用于0.1% ETB样本 (20 Hz旋转) 使用采用采用297 K的布鲁克AV-III 800 MHz谱仪,配备了T"}],"source-26":[{"source":0,"before":"图 A1.2-1 探测器调整显示器 (wobb命令) 任意探测器头.点垂直线是调整的核的共振频率.固体红线:已实现正确调整;固体黑线:调整和匹配都不正确."}],"source-29":[{"source":0,"before":"图A1.3-1 500 MHz 1H光谱中水在CDCl3中 298 K."},{"source":1,"before":"图A1.3-2 125 MHz 13C频谱中基因化在CDCl3中,在298K."}],"source-30":[{"source":0,"before":"图A1.4 (a) 使用采用BBO探测器和无样本旋转的布鲁克 Avance 500 MHz谱仪获得的CDCl3样本的残余溶剂信号对观察的线形的影响.各种状条件是"}],"source-31":[{"source":0,"before":"图A1.4 (继续)"}],"source-32":[{"source":0,"before":"图A1.5-1 显示完成的光运行,使用0.1%ETB样本的1H频谱在800MHz时获得.这显示了p1在5μs到40μs的步骤中变化.注意标志器线表示显示的第一频"}]},"navigationSections":[{"id":"section-source-11-1","pageId":"source-11","title":"OVERVIEW","titleZh":"概述","kind":"section"},{"id":"section-source-11-2","pageId":"source-11","title":"SAMPLE AND SPECTROMETER REQUIREMENTS","titleZh":"样品与谱仪要求","kind":"section"},{"id":"section-source-11-3","pageId":"source-11","title":"ACTIVITIES","titleZh":"实验内容","kind":"section"},{"id":"section-source-11-4","pageId":"source-11","title":"Part 1—Familiarization","titleZh":"第 1 部分——熟悉操作","kind":"part"},{"id":"section-source-13-5","pageId":"source-13","title":"Part 2—Shimming and Lineshape","titleZh":"第 2 部分——匀场与线形","kind":"part"},{"id":"section-source-17-6","pageId":"source-17","title":"Part 3—Pulse Calibration and Sensitivity for 1H","titleZh":"第 3 部分——1H 脉冲校准与灵敏度","kind":"part"},{"id":"section-source-19-7","pageId":"source-19","title":"Part 4—Pulse Calibration and Sensitivity for 13C","titleZh":"第 4 部分——13C 脉冲校准与灵敏度","kind":"part"},{"id":"section-source-20-8","pageId":"source-20","title":"Part 5—Viewing and Editing Text Files in TopSpin","titleZh":"第 5 部分——在 TopSpin 中查看和编辑文本文件","kind":"part"},{"id":"section-source-22-9","pageId":"source-22","title":"SUMMARY","titleZh":"总结","kind":"section"},{"id":"section-source-22-10","pageId":"source-22","title":"APPENDIX 1.1 STANDARD PARAMETER SETS","titleZh":"附录 1.1 标准参数集","kind":"section"},{"id":"section-source-25-11","pageId":"source-25","title":"APPENDIX 1.2 PROBE TUNING","titleZh":"附录 1.2 探头调谐","kind":"section"},{"id":"section-source-28-12","pageId":"source-28","title":"APPENDIX 1.3 QUININE SPECTRA","titleZh":"附录 1.3 奎宁谱","kind":"section"},{"id":"section-source-28-13","pageId":"source-28","title":"APPENDIX 1.4 LINESHAPE EFFECTS OF NONSPINNING SHIMS","titleZh":"附录 1.4 非旋转匀场线圈对线形的影响","kind":"section"},{"id":"section-source-28-14","pageId":"source-28","title":"APPENDIX 1.5 PULSE WIDTH CALIBRATION WITH PAROPT","titleZh":"附录 1.5 使用 PAROPT 校准脉冲宽度","kind":"section"}]});
